  "src/css/style.css": "/* Menue \"Funktionen\" in Liste/Ausdruck (ohne jQuery UI) */\n#menu, #menu ul { list-style: none; margin: 0; padding: 0; }\n#menu { display: inline-block; position: relative; margin: 6px 4px 6px 0; font-size: 12px; vertical-align: middle; }\n#menu > li > .menu-title { cursor: pointer; padding: 4px 10px; border: 1px solid #999; background: #f4f4f4; border-radius: 3px; display: inline-block; }\n#menu > li > ul { display: none; position: absolute; left: 0; top: 100%; z-index: 1000; background: #fff; border: 1px solid #999; min-width: 280px; box-shadow: 0 2px 6px rgba(0,0,0,.25); text-align: left; }\n#menu > li:hover > ul, #menu > li.open > ul { display: block; }\n#menu li.menu-header { padding: 4px 10px; font-weight: bold; background: #eee; border-top: 1px solid #ddd; }\n#menu li > div:not(.menu-title) { padding: 4px 10px 4px 18px; cursor: pointer; white-space: nowrap; }\n#menu li > div:not(.menu-title):hover { background: #bb0000; color: #fff; }\n\n.niu-btn { font-size: 11px; margin: 2px; padding: 3px 8px; cursor: pointer; vertical-align: middle; }\n\n.empDumpHeadRow {\n  background-color: black;\n}\n\nspan.ausblenden {\n  margin-left: 20px;\n}\n\n.suchfilter li {\n  display: inline;\n  list-style: none;\n}\n a.tooltip div.tooltiptext {\n  font-weight: normal;\n  text-align: left;\n  }\n  a.tooltip img {\n  margin-right:3px;\n  }\n  a.tooltip > span {\n  width:400px !important;\n  }\n",
